  if(tag.contains("NavigationTexture")){int t=tag.getInt("NavigationTexture");if(!tag.contains("NavigationTexture",3)||t!=-5&&t!=-2&&t!=-1&&!com.vandorlabs.neoforge.ModernFinishCatalog.validChoice(t))throw new IllegalArgumentException("Table artwork");}
